from:
.store-chips { grid-column: 2 / -1; grid-row: 2; display: flex; flex-wrap: wrap; gap: 6px; justify-content: flex-start; }
#store-sub + #store-search-box { grid-row: 1; }
#page-store #store-sub { grid-column: 1; }

to:
/* Entrances start from transparent. A window that is hidden paints no frames,
   so one that began there would stay invisible until it is shown again, and
   anything that inspects a hidden window would find it empty. kinetic.js
   sets data-kinetic only while the window is visible and motion is wanted;
   without it these layers simply appear. Spinners and progress loops are not
   entrances and keep running either way. */
html:not([data-kinetic="on"]) :is(#modal-overlay, #modal-container, #context-menu, #lightbox, #lightbox-img, .toast, #palette, #palette-box,
  #shortcut-sheet, #shortcut-card, #onboard, #onboard-card, #plan-bg, #plan-sheet, #home-notice, .dtab-panel.active, #dl-focus-poster) { animation: none !important; }

/* Reduced motion: state changes still happen, they just do not travel. */
